import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import axios from '../../index.js';
import AxiosError from '../../lib/core/AxiosError.js';

class MockXMLHttpRequest {
  constructor() {
    this.requestHeaders = {};
    this.responseHeaders = {};
    this.readyState = 0;
    this.status = 0;
    this.statusText = '';
    this.responseText = '';
    this.response = null;
    this.responseURL = '';
    this.timeout = 0;
    this.withCredentials = false;
    this.onreadystatechange = null;
    this.onloadend = null;
    this.onabort = null;
    this.onerror = null;
    this.ontimeout = null;
    this.upload = {
      addEventListener() {},
    };
  }

  open(method, url, async = true) {
    this.method = method;
    this.url = url;
    this.async = async;
  }

  setRequestHeader(key, value) {
    this.requestHeaders[key] = value;
  }

  addEventListener() {}

  getAllResponseHeaders() {
    return Object.entries(this.responseHeaders)
      .map(([key, value]) => `${key}: ${value}`)
      .join('\n');
  }

  send(data) {
    this.params = data;
    this.readyState = 1;
    requests.push(this);
  }

  respondWith({
    status = 200,
    statusText = 'OK',
    responseText = '',
    response = null,
    headers = {},
    responseURL = '',
  } = {}) {
    this.status = status;
    this.statusText = statusText;
    this.responseText = responseText;
    this.response = response;
    this.responseHeaders = headers;
    this.responseURL = responseURL;
    this.readyState = 4;
    this.finish();
  }

  responseTimeout() {
    if (this.ontimeout) {
      this.ontimeout();
    }
  }

  failNetworkError(message = 'Network Error') {
    if (this.onerror) {
      this.onerror({ message });
    }
  }

  abort() {
    if (this.onabort) {
      this.onabort();
    }
  }

  finish() {
    queueMicrotask(() => {
      if (this.onloadend) {
        this.onloadend();
      } else if (this.onreadystatechange) {
        this.onreadystatechange();
      }
    });
  }
}

let requests = [];
let OriginalXMLHttpRequest;

describe('native XHR scheme casing', () => {
  it.each(['data:', 'DATA:', 'DaTa:'])('decodes a %s URL', async (scheme) => {
    const response = await axios.get(scheme + 'text/plain,Hello%20World', {
      adapter: 'xhr',
      responseType: 'text',
    });

    expect(response.status).toBe(200);
    expect(response.data).toBe('Hello World');
  });
});

const startRequest = (...args) => {
  const promise = axios(...args);
  const request = requests.at(-1);
  expect(request).toBeDefined();

  return { request, promise };
};

const flushSuccess = async (request, promise) => {
  request.respondWith({ status: 200 });
  await promise;
};

describe('requests (vitest browser)', () => {
  beforeEach(() => {
    requests = [];
    OriginalXMLHttpRequest = window.XMLHttpRequest;
    window.XMLHttpRequest = MockXMLHttpRequest;
  });

  afterEach(() => {
    window.XMLHttpRequest = OriginalXMLHttpRequest;
    vi.restoreAllMocks();
  });

  it.each([200, 500])('reports elapsed adapter time for XHR status %s', async (status) => {
    const clock = vi.spyOn(performance, 'now').mockReturnValue(1000);
    const { request, promise } = startRequest('/timing', { adapter: 'xhr' });
    clock.mockReturnValue(1025);
    request.respondWith({ status, responseText: '{"ok":true}' });
    const result = await promise.catch((error) => error);

    expect(axios.isAxiosError(result)).toBe(status === 500);
    const response = status === 500 ? result.response : result;
    expect(response.duration).toBe(25);
    expect(response.data).toEqual({ ok: true });
  });

  it('should treat single string arg as url', async () => {
    const { request, promise } = startRequest('/foo');

    expect(request.url).toBe('/foo');
    expect(request.method).toBe('GET');

    await flushSuccess(request, promise);
  });

  it('should treat method value as lowercase string', async () => {
    const { request, promise } = startRequest({
      url: '/foo',
      method: 'POST',
    });

    request.respondWith({ status: 200 });
    const response = await promise;

    expect(response.config.method).toBe('post');
  });

  it('should allow string arg as url, and config arg', async () => {
    const { request, promise } = startRequest('/foo', {
      method: 'post',
    });

    expect(request.url).toBe('/foo');
    expect(request.method).toBe('POST');

    await flushSuccess(request, promise);
  });

  it('should allow data', async () => {
    const { request, promise } = startRequest('/foo', {
      method: 'delete',
      data: { foo: 'bar' },
    });

    expect(request.params).toBe(JSON.stringify({ foo: 'bar' }));

    await flushSuccess(request, promise);
  });

  it('should make an http request', async () => {
    const { request, promise } = startRequest('/foo');

    expect(request.url).toBe('/foo');

    await flushSuccess(request, promise);
  });

  describe('timeouts', () => {
    it('should handle timeouts', async () => {
      const { request, promise } = startRequest({
        url: '/foo',
        timeout: 100,
      });

      request.responseTimeout();

      const err = await promise.catch((error) => error);

      expect(err).toBeInstanceOf(Error);
      expect(err.code).toBe('ECONNABORTED');
    });

    describe('transitional.clarifyTimeoutError', () => {
      it('should throw ETIMEDOUT instead of ECONNABORTED on request timeouts', async () => {
        const { request, promise } = startRequest({
