    expect(reason).toBeInstanceOf(Error);
    expect(reason.config.method).toBe('get');
    expect(reason.config.url).toBe('http://thisisnotaserver/foo');
    expect(reason.request).toBeInstanceOf(MockXMLHttpRequest);
