      axios.get('ftp:localhost', {
        adapter: 'xhr',
        cancelToken: source.token,
        signal: controller.signal,
      })
    ).rejects.toMatchObject({
      message: 'Unsupported protocol ftp:',
    });

    expect(source.token._listeners || []).toEqual([]);
    expect(abortListenerCount).toBe(0);
  });
});

