    });

    source.cancel('Operation canceled by the user.');

    const error = await request.catch((err) => err);

    expect(axios.isCancel(error)).to.be.true;
    expect(error.code).to.equal('ERR_CANCELED');
    expect(getRequestCount()).to.equal(1);
  });
});

