      return new Promise((resolve) => {
        const server = http.createServer(
          handler ||
            ((req, res) => {
              let body = '';
              req.on('data', (c) => (body += c));
              req.on('end', () => {
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(
                  JSON.stringify({
                    url: req.url,
                    method: req.method,
                    headers: req.headers,
                    body,
